//! FSRS-6 conformance against the pinned reference (plan Phase 9 DoD, ADR-15).
//!
//! Replays `tests/fixtures/fsrs/vectors-py-fsrs-6.3.0.json`, generated by
//! `scripts/fsrs/generate_vectors.py` from py-fsrs 6.3.0. Elapsed days are computed exactly as the
//! reference does (whole 24-hour periods); the study-day policy is tested separately.
//!
//! Tolerance: stability and difficulty within 1e-9 relative (plus 1e-12 absolute), because the
//! port uses the same operation order but `powf` may differ from CPython's `pow` in the last ulp.
//! States, steps, intervals and fuzz results must match exactly.

use std::collections::HashMap;

use langualinker_domain::fsrs::{
    FsrsParameters, MemoryState, NextInterval, Phase, ReviewInput, SchedulerConfig,
};
use langualinker_domain::review::Rating;
use serde_json::Value;

const VECTORS: &str = include_str!("../../../tests/fixtures/fsrs/vectors-py-fsrs-6.3.0.json");
const KMP_SPEC: &str = include_str!("../../../tests/fixtures/fsrs/kmp-fsrs-spec.json");

const RELATIVE: f64 = 1e-9;
const ABSOLUTE: f64 = 1e-12;

fn vectors() -> Value {
    serde_json::from_str(VECTORS).expect("vectors are JSON")
}

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .expect("array")
        .iter()
        .map(|v| v.as_f64().expect("number"))
        .collect()
}

fn parameter_sets(doc: &Value) -> HashMap<String, Vec<f64>> {
    doc["parameterSets"]
        .as_object()
        .expect("parameter sets")
        .iter()
        .map(|(name, weights)| (name.clone(), floats(weights)))
        .collect()
}

fn close(actual: f64, expected: f64) -> bool {
    (actual - expected).abs() <= ABSOLUTE + RELATIVE * expected.abs()
}

fn rating(code: i64) -> Rating {
    match code {
        1 => Rating::Again,
        2 => Rating::Hard,
        3 => Rating::Good,
        4 => Rating::Easy,
        other => panic!("rating {other}"),
    }
}

fn u32s(value: &Value) -> Vec<u32> {
    value
        .as_array()
        .expect("array")
        .iter()
        .map(|v| v.as_u64().expect("integer") as u32)
        .collect()
}

#[test]
fn reference_is_pinned() {
    let doc = vectors();
    assert_eq!(doc["reference"]["package"], "fsrs");
    assert_eq!(doc["reference"]["version"], "6.3.0");
    assert_eq!(
        doc["reference"]["wheelSha256"],
        "deb2b613c917651a48ec90dfde3b1c8808d136f8ae78ffdcc00a5ddb216db78e"
    );
    assert_eq!(
        langualinker_domain::fsrs::FSRS_VERSION,
        "fsrs-6/py-fsrs-6.3.0"
    );
}

#[test]
fn default_weights_match_the_reference_and_the_kmp_specification() {
    let doc = vectors();
    let reference = floats(&doc["parameterSets"]["default"]);
    let kmp: Value = serde_json::from_str(KMP_SPEC).unwrap();
    let kmp = floats(&kmp["parameters"]["defaultWeights"]);
    assert_eq!(reference, langualinker_domain::fsrs::DEFAULT_WEIGHTS);
    assert_eq!(kmp, langualinker_domain::fsrs::DEFAULT_WEIGHTS);
    assert_eq!(
        reference,
        langualinker_domain::deck::DeckConfigOptions::default().weights
    );
}

#[test]
fn scenarios_match_the_reference_review_by_review() {
    let doc = vectors();
    let sets = parameter_sets(&doc);
    let scenarios = doc["scenarios"].as_array().unwrap();
    assert!(scenarios.len() >= 40, "every scenario family is present");
    let mut checked = 0;
    for scenario in scenarios {
        let id = scenario["id"].as_str().unwrap();
        let config = SchedulerConfig {
            parameters: FsrsParameters::new(
                &sets[scenario["parameters"].as_str().unwrap()],
                scenario["desiredRetention"].as_f64().unwrap(),
                scenario["maximumIntervalDays"].as_u64().unwrap() as u32,
            )
            .unwrap_or_else(|e| panic!("{id}: {e}")),
            learning_steps_seconds: u32s(&scenario["learningStepsSeconds"]),
            relearning_steps_seconds: u32s(&scenario["relearningStepsSeconds"]),
            fuzz: false,
        };
        let mut phase = Phase::Learning { step: 0 };
        let mut memory: Option<MemoryState> = None;
        let mut last_review: Option<i64> = None;
        for (index, review) in scenario["reviews"].as_array().unwrap().iter().enumerate() {
            let at = review["atSeconds"].as_i64().unwrap();
            let input = ReviewInput {
                phase,
                memory,
                // Whole 24-hour periods, floored, like `timedelta.days`.
                elapsed_days: last_review.map(|last| (at - last).div_euclid(86_400)),
            };
            let out = config.review(&input, rating(review["rating"].as_i64().unwrap()), 0.0);
            let expect = &review["expect"];
            let context = format!("{id} review #{index}");
            let (state, step) = match out.phase {
                Phase::Learning { step } => ("Learning", Some(step)),
                Phase::Review => ("Review", None),
                Phase::Relearning { step } => ("Relearning", Some(step)),
            };
            assert_eq!(state, expect["state"].as_str().unwrap(), "{context}: state");
            assert_eq!(
                step.map(u64::from),
                expect["step"].as_u64(),
                "{context}: step"
            );
            let stability = expect["stability"].as_f64().unwrap();
            let difficulty = expect["difficulty"].as_f64().unwrap();
            assert!(
                close(out.memory.stability, stability),
                "{context}: stability {} vs {stability}",
                out.memory.stability
            );
            assert!(
                close(out.memory.difficulty, difficulty),
                "{context}: difficulty {} vs {difficulty}",
                out.memory.difficulty
            );
            assert_eq!(
                out.interval.seconds(),
                expect["intervalSeconds"].as_i64().unwrap(),
                "{context}: interval"
            );
            if let NextInterval::Days(days) = out.interval {
                assert!(days >= 1 && days <= config.parameters.maximum_interval_days());
            }
            phase = out.phase;
            memory = Some(out.memory);
            last_review = Some(at);
            checked += 1;
        }
    }
    assert!(checked > 1_000, "only {checked} reviews checked");
}

#[test]
fn required_scenario_families_and_parameter_sets_are_covered() {
    let doc = vectors();
    let ids: Vec<&str> = doc["scenarios"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| s["id"].as_str().unwrap())
        .collect();
    for family in [
        "all-good",
        "all-again",
        "alternating",
        "mature-lapse",
        "same-day",
        "two-year-gap",
        "seeded-200",
    ] {
        for set in ["default", "optimized", "lowerBounds", "upperBounds"] {
            let id = format!("{family}/{set}");
            assert!(ids.contains(&id.as_str()), "missing {id}");
        }
    }
    let seeded = doc["scenarios"]
        .as_array()
        .unwrap()
        .iter()
        .find(|s| s["id"] == "seeded-200/default")
        .unwrap();
    assert_eq!(seeded["reviews"].as_array().unwrap().len(), 200);
}

#[test]
fn fuzz_matches_the_reference() {
    let doc = vectors();
    for vector in doc["fuzz"].as_array().unwrap() {
        let maximum = vector["maximumIntervalDays"].as_u64().unwrap() as u32;
        let params =
            FsrsParameters::new(&langualinker_domain::fsrs::DEFAULT_WEIGHTS, 0.9, maximum).unwrap();
        let days = vector["intervalDays"].as_u64().unwrap() as u32;
        let uniform = vector["uniform"].as_f64().unwrap();
        assert_eq!(
            u64::from(params.fuzzed_interval_days(days, uniform)),
            vector["fuzzedDays"].as_u64().unwrap(),
            "{vector}"
        );
    }
}

#[test]
fn retrievability_matches_the_reference() {
    let doc = vectors();
    let sets = parameter_sets(&doc);
    for vector in doc["retrievability"].as_array().unwrap() {
        let params =
            FsrsParameters::new(&sets[vector["parameters"].as_str().unwrap()], 0.9, 36_500)
                .unwrap();
        let actual = params.retrievability(
            vector["elapsedDays"].as_f64().unwrap(),
            vector["stability"].as_f64().unwrap(),
        );
        let expected = vector["retrievability"].as_f64().unwrap();
        assert!(close(actual, expected), "{vector}: {actual}");
    }
}

#[test]
fn intervals_match_the_reference() {
    let doc = vectors();
    let sets = parameter_sets(&doc);
    for vector in doc["intervals"].as_array().unwrap() {
        let params = FsrsParameters::new(
            &sets[vector["parameters"].as_str().unwrap()],
            vector["desiredRetention"].as_f64().unwrap(),
            36_500,
        )
        .unwrap();
        assert_eq!(
            u64::from(params.next_interval_days(vector["stability"].as_f64().unwrap())),
            vector["intervalDays"].as_u64().unwrap(),
            "{vector}"
        );
    }
}
